    name_pl = EXCLUDED.name_pl, why_en = EXCLUDED.why_en, why_pl = EXCLUDED.why_pl, how_en = EXCLUDED.how_en,
    how_pl = EXCLUDED.how_pl, aliases_en = EXCLUDED.aliases_en, aliases_pl = EXCLUDED.aliases_pl, sources = EXCLUDED.sources;
