INSERT INTO food_safety_item (code, level, quick_order, name_en, name_pl, why_en, why_pl, how_en, how_pl, aliases_en, aliases_pl, sources)
VALUES
    ('GRAPES', 'NEVER', 1, 'Grapes, raisins, currants', 'Winogrona, rodzynki, suszone porzeczki', 'Kidney failure, even from a small amount. Also hidden in makowiec, keks and Christmas baking.', 'Niewydolność nerek, nawet po małej ilości. Rodzynki ukrywają się też w makowcu, keksie i świątecznych wypiekach.', 'Call your vet now, even if she seems fine. Have the packet and her weight ready.', 'Zadzwoń do weterynarza od razu, nawet jeśli wygląda dobrze. Przygotuj opakowanie i jej wagę.', ARRAY['raisins', 'sultanas', 'currants', 'fruitcake']::text[], ARRAY['rodzynki', 'sułtanki', 'makowiec', 'keks']::text[], ARRAY['ASPCA', 'PPH', 'HILLS', 'WSAVA']::varchar[]),
    ('CHOCOLATE', 'NEVER', 2, 'Chocolate, cocoa', 'Czekolada, kakao', 'Theobromine and caffeine. Dark chocolate and baking cocoa are worst. Vomiting, fast heart rate, tremors, seizures.', 'Teobromina i kofeina. Najgorsza jest ciemna czekolada i kakao do pieczenia. Wymioty, szybkie bicie serca, drżenie, drgawki.', 'Call your vet now, even if she seems fine. Have the packet and her weight ready.', 'Zadzwoń do weterynarza od razu, nawet jeśli wygląda dobrze. Przygotuj opakowanie i jej wagę.', ARRAY['cocoa', 'brownie', 'cacao']::text[], ARRAY['kakao', 'brownie', 'czekoladki']::text[], ARRAY['ASPCA', 'PPH', 'AKC', 'WSAVA']::varchar[]),
    ('SUGAR_FREE_GUM', 'NEVER', 9, 'Xylitol (sugar-free gum, sweets)', 'Ksylitol (guma bez cukru, słodycze)', 'Blood sugar drops fast, then liver damage. A small amount is enough. Signs can start within 30 minutes. Also in some peanut butters and baked goods.', 'Cukier we krwi gwałtownie spada, potem dochodzi do uszkodzenia wątroby. Wystarczy mała ilość. Objawy mogą pojawić się w ciągu 30 minut. Ksylitol bywa też w masłach orzechowych i wypiekach.', 'Call your vet now, even if she seems fine. Have the packet and her weight ready.', 'Zadzwoń do weterynarza od razu, nawet jeśli wygląda dobrze. Przygotuj opakowanie i jej wagę.', ARRAY['xylitol', 'sugar-free gum', 'chewing gum', 'birch sugar']::text[], ARRAY['ksylitol', 'guma bez cukru', 'guma do żucia', 'cukier brzozowy']::text[], ARRAY['ASPCA', 'PPH']::varchar[]),
    ('ONION_GARLIC', 'NEVER', NULL, 'Onion, garlic, chives, leek, shallot', 'Cebula, czosnek, szczypiorek, por, szalotka', 'Damages red blood cells and can cause anaemia. Raw, cooked or powdered. Garlic is stronger than onion. Signs can be delayed by days.', 'Uszkadza czerwone krwinki i może powodować anemię. Surowe, gotowane i w proszku. Czosnek jest silniejszy niż cebula. Objawy mogą pojawić się dopiero po kilku dniach.', 'Call your vet now, even if she seems fine. Have the packet and her weight ready.', 'Zadzwoń do weterynarza od razu, nawet jeśli wygląda dobrze. Przygotuj opakowanie i jej wagę.', ARRAY['onion', 'garlic', 'chives', 'leek', 'shallot']::text[], ARRAY['cebula', 'czosnek', 'szczypiorek', 'por', 'szalotka']::text[], ARRAY['ASPCA', 'PPH', 'AKC', 'HILLS', 'WSAVA']::varchar[]),
    ('CAFFEINE', 'NEVER', NULL, 'Coffee, tea, energy drinks', 'Kawa, herbata, napoje energetyczne', 'Stimulant. Panting, tremors, high blood pressure.', 'Substancja pobudzająca. Zadyszka, drżenie, wysokie ciśnienie krwi.', NULL, NULL, ARRAY['caffeine', 'coffee', 'tea', 'energy drink']::text[], ARRAY['kofeina', 'kawa', 'herbata', 'energetyk']::text[], ARRAY['ASPCA', 'PPH', 'WSAVA']::varchar[]),
    ('MACADAMIA', 'NEVER', NULL, 'Macadamia nuts', 'Orzechy makadamia', 'Weakness (often in the back legs), tremors, vomiting, high temperature.', 'Osłabienie (często tylnych łap), drżenie, wymioty, wysoka temperatura.', NULL, NULL, ARRAY['macadamia']::text[], ARRAY['makadamia']::text[], ARRAY['ASPCA', 'PPH', 'AKC', 'WSAVA']::varchar[]),
    ('ALCOHOL', 'NEVER', NULL, 'Alcohol, food made with alcohol', 'Alkohol, potrawy z alkoholem', 'Rapidly absorbed. Wobbling, breathing problems, coma.', 'Szybko się wchłania. Chwiejny chód, problemy z oddychaniem, śpiączka.', NULL, NULL, ARRAY['beer', 'wine', 'vodka']::text[], ARRAY['piwo', 'wino', 'wódka']::text[], ARRAY['ASPCA', 'PPH', 'HILLS', 'WSAVA']::varchar[]),
    ('RAW_YEAST_DOUGH', 'NEVER', NULL, 'Raw yeast dough', 'Surowe ciasto drożdżowe', 'Rises in the stomach, causes painful bloating and can twist the stomach (emergency). Yeast also makes alcohol.', 'Rośnie w żołądku, powoduje bolesne wzdęcie i może skręcić żołądek (nagły przypadek). Drożdże wytwarzają też alkohol.', 'Call your vet now, even if she seems fine. Have the packet and her weight ready.', 'Zadzwoń do weterynarza od razu, nawet jeśli wygląda dobrze. Przygotuj opakowanie i jej wagę.', ARRAY['dough', 'yeast']::text[], ARRAY['ciasto', 'drożdże']::text[], ARRAY['ASPCA', 'WSAVA']::varchar[]),
    ('BONES', 'NEVER', NULL, 'Bones, cooked or raw', 'Kości, gotowane i surowe', 'Splinter, block or tear the gut or throat. WSAVA says avoid both cooked and raw.', 'Mogą się łamać na ostre kawałki, zablokować lub uszkodzić jelita i gardło. WSAVA zaleca unikać zarówno gotowanych, jak i surowych.', NULL, NULL, ARRAY['bone', 'chicken bone']::text[], ARRAY['kość', 'kostka']::text[], ARRAY['WSAVA', 'ASPCA']::varchar[]),
    ('CORN_COB', 'NEVER', NULL, 'Corn on the cob', 'Kolba kukurydzy', 'The cob blocks the gut. Corn kernels off the cob are fine.', 'Kolba blokuje jelita. Ziarna kukurydzy zdjęte z kolby są w porządku.', NULL, NULL, ARRAY['cob', 'sweetcorn on the cob']::text[], ARRAY['kolba']::text[], ARRAY['AKC']::varchar[]),
    ('SALTY_FOOD', 'NEVER', NULL, 'Salty food (chips, salty snacks, brine)', 'Słone przekąski, solone potrawy', 'Too much salt: thirst, vomiting, tremors, seizures.', 'Zbyt dużo soli: pragnienie, wymioty, drżenie, drgawki.', NULL, NULL, ARRAY['crisps', 'chips', 'pretzels', 'brine']::text[], ARRAY['chipsy', 'paluszki', 'solone', 'zalewa']::text[], ARRAY['ASPCA']::varchar[]),
    ('MOULDY_FOOD', 'NEVER', NULL, 'Mouldy food, compost', 'Spleśniałe jedzenie, kompost', 'Tremors, seizures.', 'Drżenie, drgawki.', NULL, NULL, ARRAY['mold', 'compost']::text[], ARRAY['pleśń', 'kompost']::text[], ARRAY['PPH']::varchar[]),
    ('NUTMEG', 'NEVER', NULL, 'Nutmeg', 'Gałka muszkatołowa', 'Toxic spice. Used in Christmas baking.', 'Toksyczna przyprawa. Używana w świątecznych wypiekach.', NULL, NULL, ARRAY[]::text[], ARRAY['muszkatołowa']::text[], ARRAY['GEN']::varchar[]),
    ('ALMONDS', 'NEVER', NULL, 'Almonds', 'Migdały', 'Choking risk, and fatty nuts can cause stomach upset and pancreatitis. Sources disagree, so the cautious answer is shown.', 'Ryzyko zadławienia, a tłuste orzechy mogą powodować rozstrój żołądka i zapalenie trzustki. Źródła się różnią, dlatego pokazujemy ostrożną odpowiedź.', NULL, NULL, ARRAY['almond']::text[], ARRAY['migdał']::text[], ARRAY['AKC', 'HILLS', 'ASPCA']::varchar[]),
    ('CITRUS', 'NEVER', NULL, 'Citrus (orange, tangerine, lemon)', 'Cytrusy (pomarańcza, mandarynka, cytryna)', 'Peel, seeds and juice upset the stomach. Sources disagree about small amounts of flesh, so the cautious answer is shown.', 'Skórka, pestki i sok drażnią żołądek. Źródła różnią się w sprawie małych ilości miąższu, dlatego pokazujemy ostrożną odpowiedź.', NULL, NULL, ARRAY['orange', 'tangerine', 'lemon', 'mandarin', 'grapefruit']::text[], ARRAY['pomarańcza', 'mandarynka', 'cytryna', 'grejpfrut']::text[], ARRAY['HILLS', 'ASPCA']::varchar[]),
    ('CHEESE', 'LITTLE', 3, 'Cheese', 'Ser', 'High in fat. Some dogs cannot digest lactose.', 'Dużo tłuszczu. Niektóre psy nie trawią laktozy.', 'Small cube. Lower-fat types (cottage cheese, mozzarella). Counts as a treat.', 'Mała kostka. Lepsze są chudsze rodzaje (twaróg, mozzarella). Liczy się jako smakołyk.', ARRAY['cottage cheese', 'mozzarella']::text[], ARRAY['twaróg', 'mozzarella', 'żółty ser']::text[], ARRAY['AKC', 'WSAVA']::varchar[]),
    ('MILK_ICE_CREAM', 'LITTLE', NULL, 'Milk, ice cream', 'Mleko, lody', 'Little lactase, so diarrhoea. Ice cream is also high in sugar.', 'Mało laktazy, więc biegunka. Lody mają też dużo cukru.', 'A few licks at most. Water is better. Frozen apple or berries instead of ice cream.', 'Co najwyżej kilka liźnięć. Lepsza jest woda. Zamiast lodów mrożone jabłko lub jagody.', ARRAY['milk', 'ice cream']::text[], ARRAY['mleko', 'lody']::text[], ARRAY['ASPCA', 'AKC']::varchar[]),
    ('PEANUT_BUTTER', 'LITTLE', NULL, 'Peanut butter', 'Masło orzechowe', 'Fine for dogs, but calorie dense (about 81 kcal a tablespoon) and sometimes contains xylitol.', 'Dla psów jest w porządku, ale bardzo kaloryczne (ok. 81 kcal w łyżce) i czasem zawiera ksylitol.', 'Thin smear. Unsalted. Read the label for xylitol first.', 'Cienka warstwa. Niesolone. Najpierw sprawdź na etykiecie, czy nie ma ksylitolu.', ARRAY['peanut']::text[], ARRAY['orzechowe']::text[], ARRAY['AKC', 'WSAVA', 'PPH']::varchar[]),
    ('BREAD', 'LITTLE', 8, 'Plain bread', 'Zwykły chleb', 'No value, many calories.', 'Brak wartości odżywczej, dużo kalorii.', 'A bite. Never raw dough, never with raisins, seeds or spices.', 'Jeden kęs. Nigdy surowe ciasto ani chleb z rodzynkami, ziarnami czy przyprawami.', ARRAY['toast', 'roll']::text[], ARRAY['bułka', 'tost']::text[], ARRAY['AKC']::varchar[]),
    ('BANANA', 'LITTLE', 5, 'Banana', 'Banan', 'High in sugar.', 'Dużo cukru.', 'A thin slice, peeled, not every day.', 'Cienki plasterek, obrany, nie codziennie.', ARRAY[]::text[], ARRAY[]::text[], ARRAY['HILLS']::varchar[]),
    ('COOKED_FISH', 'LITTLE', NULL, 'Cooked fish (not tuna every day)', 'Gotowana ryba', 'Good fats. Raw fish can carry parasites. Canned tuna has mercury and salt.', 'Dobre tłuszcze. Surowa ryba może nosić pasożyty. Tuńczyk z puszki zawiera rtęć i sól.', 'Fully cooked, cooled, boneless. Fish no more than twice a week. Tuna in water, small amount.', 'W pełni ugotowana, ostudzona, bez ości. Ryba najwyżej dwa razy w tygodniu. Tuńczyk w wodzie, mała ilość.', ARRAY['fish', 'tuna', 'cod']::text[], ARRAY['ryba', 'tuńczyk', 'dorsz']::text[], ARRAY['AKC']::varchar[]),
    ('COOKED_SHRIMP', 'LITTLE', NULL, 'Cooked shrimp', 'Gotowane krewetki', 'Low fat. Shell is a choking and gut risk.', 'Mało tłuszczu. Skorupa grozi zadławieniem i uszkodzeniem jelit.', 'Occasional. Fully cooked, shell, head, tail and legs removed.', 'Okazjonalnie. W pełni ugotowane, bez skorupy, głowy, ogona i nóżek.', ARRAY['prawn', 'shrimp']::text[], ARRAY['krewetka']::text[], ARRAY['AKC']::varchar[]),
    ('HAM', 'LITTLE', NULL, 'Ham, cured meats', 'Szynka, wędliny', 'High in salt and fat.', 'Dużo soli i tłuszczu.', 'Small pieces, not a habit.', 'Małe kawałki, nie jako nawyk.', ARRAY['sausage', 'bacon', 'salami']::text[], ARRAY['kiełbasa', 'boczek', 'salami']::text[], ARRAY['AKC']::varchar[]),
    ('PORK', 'LITTLE', NULL, 'Pork', 'Wieprzowina', 'Digestible but fatty.', 'Strawna, ale tłusta.', 'Plain, cooked, trimmed of fat, no seasoning.', 'Naturalna, ugotowana, bez tłuszczu i przypraw.', ARRAY[]::text[], ARRAY[]::text[], ARRAY['AKC']::varchar[]),
    ('UNSALTED_NUTS', 'LITTLE', NULL, 'Unsalted peanuts, cashews', 'Niesolone orzeszki ziemne, nerkowce', 'Fat can cause pancreatitis. Hard for a toy breed to chew.', 'Tłuszcz może wywołać zapalenie trzustki. Trudne do rozgryzienia dla ras toy.', 'A few, unsalted, no shells.', 'Kilka sztuk, niesolone, bez łupin.', ARRAY['cashew', 'peanuts']::text[], ARRAY['nerkowce', 'orzeszki']::text[], ARRAY['AKC', 'ASPCA']::varchar[]),
    ('POPCORN', 'LITTLE', NULL, 'Popcorn', 'Popcorn', 'Unpopped kernels are a choking hazard.', 'Niewypukane ziarna grożą zadławieniem.', 'Plain, air-popped, no salt or butter, fully popped.', 'Naturalny, prażony bez tłuszczu, bez soli i masła, w pełni wypukany.', ARRAY[]::text[], ARRAY[]::text[], ARRAY['AKC']::varchar[]),
    ('HONEY', 'LITTLE', NULL, 'Honey', 'Miód', 'Sugar.', 'Cukier.', 'A small lick, rarely.', 'Małe liźnięcie, rzadko.', ARRAY[]::text[], ARRAY[]::text[], ARRAY['AKC']::varchar[]),
    ('COCONUT', 'LITTLE', NULL, 'Coconut', 'Kokos', 'Oils can loosen the stool.', 'Oleje mogą rozluźnić stolec.', 'A small piece without husk. Sources disagree.', 'Mały kawałek bez łupiny. Źródła się różnią.', ARRAY[]::text[], ARRAY[]::text[], ARRAY['AKC', 'ASPCA']::varchar[]),
    ('AVOCADO', 'LITTLE', NULL, 'Avocado flesh', 'Awokado', 'Fat can cause pancreatitis, persin may upset the stomach, the pit blocks the gut.', 'Tłuszcz może wywołać zapalenie trzustki, persyna może drażnić żołądek, a pestka blokuje jelita.', 'Tiny piece of flesh only. No skin, no pit.', 'Tylko malutki kawałek miąższu. Bez skórki i pestki.', ARRAY[]::text[], ARRAY[]::text[], ARRAY['HILLS']::varchar[]),
    ('CINNAMON', 'LITTLE', NULL, 'Cinnamon', 'Cynamon', 'Sources disagree: AKC says avoid, ASPCA lists it as non-toxic.', 'Źródła się różnią: AKC zaleca unikać, ASPCA uznaje za nietoksyczny.', 'A sprinkle, not a spoon.', 'Szczypta, nie łyżeczka.', ARRAY[]::text[], ARRAY[]::text[], ARRAY['AKC', 'ASPCA']::varchar[]),
    ('CARROT', 'YES', 4, 'Carrot', 'Marchewka', 'Low calorie, fibre, good for chewing.', 'Mało kalorii, dużo błonnika, dobra do gryzienia.', 'Raw or cooked, cut small. Introduce slowly.', 'Surowa lub gotowana, pokrojona na małe kawałki. Wprowadzaj powoli.', ARRAY['carrots']::text[], ARRAY['marchew']::text[], ARRAY['HILLS']::varchar[]),
    ('GREEN_BEANS', 'YES', NULL, 'Green beans', 'Fasolka szparagowa', 'Low calorie, fibre.', 'Mało kalorii, dużo błonnika.', 'Plain, no salt or butter.', 'Naturalna, bez soli i masła.', ARRAY['beans']::text[], ARRAY['fasola']::text[], ARRAY['HILLS']::varchar[]),
    ('PEAS', 'YES', NULL, 'Peas', 'Groszek', 'Low calorie, fibre.', 'Mało kalorii, dużo błonnika.', 'Plain, no salt or butter.', 'Naturalny, bez soli i masła.', ARRAY['pea']::text[], ARRAY['groszek zielony']::text[], ARRAY['HILLS']::varchar[]),
    ('SWEET_POTATO', 'YES', NULL, 'Sweet potato', 'Batat', 'Fibre and vitamins.', 'Błonnik i witaminy.', 'Cooked only, plain.', 'Tylko ugotowany, naturalny.', ARRAY[]::text[], ARRAY['słodki ziemniak']::text[], ARRAY['HILLS']::varchar[]),
    ('APPLE', 'YES', 6, 'Apple', 'Jabłko', 'Fibre and vitamins A and C.', 'Błonnik oraz witaminy A i C.', 'Small pieces. No core, no seeds, no stem or leaves.', 'Małe kawałki. Bez gniazda nasiennego, pestek, szypułki i liści.', ARRAY[]::text[], ARRAY[]::text[], ARRAY['HILLS']::varchar[]),
    ('BLUEBERRIES', 'YES', NULL, 'Blueberries', 'Borówki', 'Antioxidants, low calorie.', 'Antyoksydanty, mało kalorii.', 'A few at a time.', 'Kilka sztuk naraz.', ARRAY['blueberry', 'berries']::text[], ARRAY['jagody', 'borówka']::text[], ARRAY['HILLS']::varchar[]),
    ('MELON', 'YES', NULL, 'Melon', 'Melon', 'Water and vitamins.', 'Woda i witaminy.', 'Seeds and rind removed.', 'Bez pestek i skórki.', ARRAY['cantaloupe', 'honeydew']::text[], ARRAY[]::text[], ARRAY['HILLS']::varchar[]),
    ('RIPE_TOMATO', 'YES', NULL, 'Ripe red tomato', 'Dojrzały pomidor', 'Ripe fruit is fine. Green parts (stem, leaves, unripe) are toxic.', 'Dojrzały owoc jest w porządku. Zielone części (łodyga, liście, niedojrzałe) są toksyczne.', 'A slice, ripe and red only.', 'Plasterek, tylko dojrzały i czerwony.', ARRAY['tomato']::text[], ARRAY['pomidor']::text[], ARRAY['HILLS']::varchar[]),
    ('COOKED_EGG', 'YES', NULL, 'Cooked egg', 'Jajko na twardo', 'Good protein.', 'Dobre białko.', 'Fully cooked, plain. Raw egg white affects biotin.', 'W pełni ugotowane, naturalne. Surowe białko jaja wpływa na biotynę.', ARRAY['egg', 'boiled egg']::text[], ARRAY['jajko', 'jajo']::text[], ARRAY['AKC', 'ASPCA']::varchar[]),
    ('COOKED_TURKEY', 'YES', NULL, 'Cooked turkey', 'Gotowany indyk', 'Lean meat.', 'Chude mięso.', 'No skin, fat, bones, salt, onion or garlic.', 'Bez skóry, tłuszczu, kości, soli, cebuli i czosnku.', ARRAY['turkey']::text[], ARRAY['indyk']::text[], ARRAY['AKC']::varchar[]),
    ('COOKED_CHICKEN', 'YES', 7, 'Cooked chicken', 'Gotowany kurczak', 'Lean protein, a classic training treat.', 'Chude białko, klasyczny smakołyk treningowy.', 'Plain, no skin, bones, salt or spices.', 'Naturalny, bez skóry, kości, soli i przypraw.', ARRAY['chicken']::text[], ARRAY['kurczak']::text[], ARRAY['GEN']::varchar[]),
    ('COOKED_SALMON', 'YES', NULL, 'Cooked salmon', 'Gotowany łosoś', 'Protein and omega fats.', 'Białko i kwasy omega.', 'Fully cooked only. Raw or undercooked salmon carries parasites.', 'Tylko w pełni ugotowany. Surowy lub niedogotowany łosoś może nosić pasożyty.', ARRAY['salmon']::text[], ARRAY['losos']::text[], ARRAY['AKC']::varchar[]),
    ('PLAIN_YOGURT', 'YES', NULL, 'Plain yogurt', 'Jogurt naturalny', 'Probiotics, if she tolerates dairy.', 'Probiotyki, jeśli toleruje nabiał.', 'Plain only. No sugar or sweeteners (xylitol).', 'Tylko naturalny. Bez cukru i słodzików (ksylitol).', ARRAY['yoghurt']::text[], ARRAY['jogurt']::text[], ARRAY['AKC']::varchar[]),
    ('CORN_KERNELS', 'YES', NULL, 'Corn kernels (off the cob)', 'Kukurydza (ziarna)', 'Fine as an ingredient.', 'W porządku jako składnik.', 'Off the cob only.', 'Tylko zdjęta z kolby.', ARRAY['sweetcorn', 'corn']::text[], ARRAY['kukurydza']::text[], ARRAY['AKC']::varchar[]),
    ('CUCUMBER', 'YES', NULL, 'Cucumber', 'Ogórek', 'Low calorie, water and fibre.', 'Mało kalorii, woda i błonnik.', 'Small pieces, plain.', 'Małe kawałki, naturalny.', ARRAY[]::text[], ARRAY[]::text[], ARRAY['GEN']::varchar[]),
    ('PUMPKIN', 'YES', NULL, 'Pumpkin (plain, cooked)', 'Dynia (ugotowana)', 'Low calorie, water and fibre.', 'Mało kalorii, woda i błonnik.', 'Small pieces, plain, cooked.', 'Małe kawałki, naturalna, ugotowana.', ARRAY[]::text[], ARRAY[]::text[], ARRAY['GEN']::varchar[]),
    ('COURGETTE', 'YES', NULL, 'Courgette', 'Cukinia', 'Low calorie, water and fibre.', 'Mało kalorii, woda i błonnik.', 'Small pieces, plain.', 'Małe kawałki, naturalna.', ARRAY['zucchini']::text[], ARRAY[]::text[], ARRAY['GEN']::varchar[]),
    ('WATERMELON', 'YES', NULL, 'Watermelon (no seeds or rind)', 'Arbuz (bez pestek i skórki)', 'Low calorie, water and fibre.', 'Mało kalorii, woda i błonnik.', 'Small pieces, seeds and rind removed.', 'Małe kawałki, bez pestek i skórki.', ARRAY[]::text[], ARRAY[]::text[], ARRAY['GEN']::varchar[])
